import{_ as t,C as a,o as i,c as s,j as r,a as n,E as d,a2 as l}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Dérive","description":"","frontmatter":{"title":"Dérive"},"headers":[],"relativePath":"guide/drift.md","filePath":"guide/drift.md"}'),u={name:"guide/drift.md"};function c(h,e,f,p,v,g){const o=a("Capture");return i(),s("div",null,[e[0]||(e[0]=r("h1",{id:"derive",tabindex:"-1"},[n("Dérive "),r("a",{class:"header-anchor",href:"#derive","aria-label":'Permalink to "Dérive"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Cet écran vérifie que le code modifié correspond bien à du travail déclaré. Vous y venez avant un commit, ou quand un agent a touché au code, pour savoir si la règle « pas de code sans tâche en cours » est respectée.",-1)),d(o,{name:"derive",alt:"L'écran Dérive : verdict Aucune dérive, tâche active Oui, liste des fichiers de code modifiés"}),e[2]||(e[2]=l('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>Sous le titre <strong>Détecteur de dérive</strong>, une carte réunit :</p><ul><li>Le <strong>verdict</strong> : <strong>Aucune dérive</strong> (fond vert) ou <strong>Dérive détectée</strong> (fond orange).</li><li><strong>Tâche active</strong> : <strong>Oui</strong> si au moins une tâche du projet est <strong>En cours</strong>, quelle que soit sa story — c&#39;est la règle du hook anti-dérive au commit ; <strong>Non</strong> sinon.</li><li><strong>Fichiers de code modifiés</strong> : la liste des fichiers de code modifiés dans le dépôt. S&#39;il n&#39;y en a pas, l&#39;écran affiche « Aucun fichier de code modifié. » Les stacks qui déclarent leur propre dépôt sont aussi interrogées ; leurs fichiers sont préfixés par l&#39;identifiant de la stack.</li><li>Deux boutons : <strong>Rafraîchir</strong> et <strong>Installer le hook pre-commit</strong>.</li></ul><h2 id="quand-y-a-t-il-derive" tabindex="-1">Quand y a-t-il dérive ? <a class="header-anchor" href="#quand-y-a-t-il-derive" aria-label="Permalink to &quot;Quand y a-t-il dérive ?&quot;">​</a></h2><p>Il y a dérive quand des fichiers de code sont modifiés <strong>et</strong> qu&#39;aucune tâche n&#39;est <strong>En cours</strong>. Les fichiers de métadonnées (<code>.effortless/</code>, <code>blueprints/</code>) ne comptent pas comme du code.</p><p>Pour lever une dérive, passez la tâche concernée à <strong>En cours</strong> dans l&#39;écran <a href="/Effortless/guide/tasks.html">Tâches</a>, ou créez-en une.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><ul><li><strong>Rafraîchir</strong> : relit l&#39;état du dépôt. L&#39;écran se recharge aussi tout seul quand le projet change.</li><li><strong>Installer le hook pre-commit</strong> : pose un hook git qui refuse les commits de code sans tâche en cours. L&#39;écran confirme avec « Succès : Hook installé : » suivi du chemin du hook.</li><li>Quand le hook est déjà en place, le bouton devient <strong>Réinstaller le hook pre-commit</strong> et <strong>Rafraîchir</strong> passe au premier plan.</li></ul><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>N&#39;utilisez pas <code>--no-verify</code> pour contourner le hook : mieux vaut déclarer la tâche.</li><li>Si l&#39;écran affiche une erreur, vérifiez que le dossier est bien un dépôt git (<a href="/Effortless/guide/git.html">Git</a>).</li></ul><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Les agents disposent de <code>effortless_drift_check</code> pour lire le même verdict et de <code>effortless_drift_hook_install</code> pour poser le hook.</p>',12))])}const _=t(u,[["render",c]]);export{q as __pageData,_ as default};
